/**
 * @file poseidon_parity.test.ts
 *
 * Known-answer tests (KATs) for poseidon-lite over BN254 (5 inputs).
 *
 * These reference values were generated by running both poseidon-lite AND
 * circomlibjs side-by-side and confirming they produce identical outputs
 * (see git history for the cross-library parity run). circomlibjs has since
 * been removed in favour of poseidon-lite; these KATs ensure future updates
 * to poseidon-lite do not silently change the hash outputs and break
 * compatibility with the on-chain Poseidon commitment in the circuit.
 *
 * Input order: [tx_count, dispute_count, avg_balance, months_active, salt]
 * — matches the order in reputation_score.circom and computeCommitment().
 *
 * NOTE: we import poseidon-lite via its resolved file path so that jest's
 * moduleNameMapper (which maps "poseidon-lite" → the test stub) is bypassed.
 * This file needs the *real* library to validate the KAT values.
 */

// eslint-disable-next-line @typescript-eslint/no-var-requires
const { poseidon5 } = require("../../node_modules/poseidon-lite/index.js") as typeof import("poseidon-lite");

const KAT_VECTORS: Array<{ label: string; inputs: bigint[]; expected: string }> = [
  {
    label: "all zeros",
    inputs: [0n, 0n, 0n, 0n, 0n],
    expected: "14655542659562014735865511769057053982292279840403315552050801315682099828156",
  },
  {
    label: "all ones",
    inputs: [1n, 1n, 1n, 1n, 1n],
    expected: "7336984428078952600237169304321914358474313324708186973411450536267727944123",
  },
  {
    label: "typical Bronze inputs (35 txs, 1 dispute, 5000 bal, 10 months)",
    inputs: [35n, 1n, 5000n, 10n, 12345678901234567890n],
    expected: "3955449443292644464021105530544624284919081917863668637715077918826646971345",
  },
  {
    label: "typical Silver inputs (50 txs, 0 disputes, 50000 bal, 12 months)",
    inputs: [50n, 0n, 50000n, 12n, 98765432109876543210n],
    expected: "17035709177654293252164191154246751789832061842115603258572534074951407852697",
  },
  {
    label: "typical Gold inputs — max caps (50 txs, 0 disputes, 100000 bal, 12 months)",
    inputs: [50n, 0n, 100000n, 12n, 11111111111111111111n],
    expected: "670936522981779445954336061799789597959769819999957656314968702215342267319",
  },
  {
    label: "large salt (near BN254 scalar field boundary)",
    inputs: [
      42n, 3n, 8500n, 9n,
      452312848583266388373324160190187140051835877600158453279131187530910662655n,
    ],
    expected: "15242933180473764194448698170171854819281509949364910940472535024200233339454",
  },
  {
    label: "zero disputes, high tx count (200 txs — tests clean_txs cap)",
    inputs: [200n, 0n, 10000n, 24n, 999999999999999999n],
    expected: "16514711135967583188736329804213433142372726774387170332274362238370592640241",
  },
  {
    label: "all inputs at circuit caps (50 txs, 0 disputes, 10000 bal, 12 months)",
    inputs: [50n, 0n, 10000n, 12n, 1n],
    expected: "1402889806347917549404131804140863210469290583496882947481546502077220264704",
  },
];

describe("poseidon-lite — known-answer tests (BN254, 5 inputs)", () => {
  for (const { label, inputs, expected } of KAT_VECTORS) {
    test(label, () => {
      expect(poseidon5(inputs).toString()).toBe(expected);
    });
  }

  test("outputs are non-zero for non-zero inputs", () => {
    expect(poseidon5([1n, 2n, 3n, 4n, 5n])).not.toBe(0n);
  });

  test("different inputs produce different outputs (collision resistance smoke-test)", () => {
    const a = poseidon5([1n, 0n, 0n, 0n, 0n]).toString();
    const b = poseidon5([0n, 1n, 0n, 0n, 0n]).toString();
    const c = poseidon5([0n, 0n, 0n, 0n, 1n]).toString();
    expect(a).not.toBe(b);
    expect(b).not.toBe(c);
    expect(a).not.toBe(c);
  });

  test("result is a valid BN254 scalar field element (< field order r)", () => {
    // BN254 scalar field order
    const r = 21888242871839275222246405745257275088548364400416034343698204186575808495617n;
    for (const { inputs } of KAT_VECTORS) {
      expect(poseidon5(inputs) < r).toBe(true);
    }
  });
});
